from qgis.PyQt.QtWidgets import QAction, QAbstractButton, QToolBar, QWidget
mw = iface.mainWindow()
a = None
for x in mw.findChildren(QAction):
    if (x.text() or '') == 'Update GPS Information':
        a = x
        break
users = []
for w in mw.findChildren(QWidget):
    try:
        if isinstance(w, QAbstractButton) and w.defaultAction() is a:
            users.append('button ' + type(w).__name__ + '(' + w.objectName() + ')')
        elif hasattr(w, 'actions') and a in w.actions():
            users.append(type(w).__name__ + '(' + (w.objectName() or w.windowTitle() if hasattr(w,'windowTitle') else '') + ')')
    except Exception:
        pass
result = {'users': users[:20]}
"}

