from qgis.PyQt.QtWidgets import QAction, QDockWidget, QAbstractButton
mw = iface.mainWindow()
docks = [(d.objectName(), d.windowTitle(), type(d.widget()).__name__) for d in mw.findChildren(QDockWidget)]
# find GPS info dock and scan its buttons
gps_dock = None
for d in mw.findChildren(QDockWidget):
    if 'Gps' in type(d.widget()).__name__ or 'GPS' in (d.windowTitle() or ''):
        gps_dock = d
        break
btns = []
if gps_dock is not None:
    for b in gps_dock.findChildren(QAbstractButton):
        da = b.defaultAction()
        btns.append({'btn': type(b).__name__ + '(' + b.objectName() + ')', 'text': b.text(),
                     'action_text': da.text() if da else None, 'enabled': b.isEnabled()})
result = {'docks': docks, 'gps_dock': (gps_dock.objectName() if gps_dock else None), 'buttons': btns}
"}
